#define HDV 512
#define WINV 0
// iter-19 v7 (generated by gen_v7.py): column-split PV, P exchange through LDS, O pinned to a[0:255].
#include <hip/hip_runtime.h>
#include <hip/hip_bf16.h>
#include <stdint.h>

typedef int v8i __attribute__((ext_vector_type(8)));
typedef int v4i __attribute__((ext_vector_type(4)));
typedef int v2i __attribute__((ext_vector_type(2)));
typedef float v16f __attribute__((ext_vector_type(16)));
typedef __attribute__((address_space(3))) v2i lds_v2i;
typedef __attribute__((address_space(3))) void lds_void;

#define WIN_EFF (WINV > 0 ? WINV : 0x3fffffff)
#define SCHED_FENCE() __builtin_amdgcn_sched_barrier(0)

#ifndef MFMA_NOP
#define MFMA_NOP ""
#endif
#ifndef LAZY_THRESH_V
#define LAZY_THRESH_V 8.0f
#endif
#ifndef PF_DEPTH
#define PF_DEPTH 3
#endif

__device__ __forceinline__ v16f mfma_bi(const v8i& a, const v8i& b, const v16f& c) {
  return __builtin_amdgcn_mfma_scale_f32_32x32x64_f8f6f4(a, b, c, 0, 0, 0, 127, 0, 127);
}
__device__ __forceinline__ v16f mfma_bi_sb(const v8i& a, const v8i& b, const v16f& c, int sb) {
  return __builtin_amdgcn_mfma_scale_f32_32x32x64_f8f6f4(a, b, c, 0, 0, 0, 127, 0, sb);
}
__device__ __forceinline__ void mfma_s0(v16f& d, const v8i& a, const v8i& b) {
  v16f z;
#pragma unroll
  for (int i = 0; i < 16; i++) z[i] = 0.f;
  d = mfma_bi(a, b, z);
}
__device__ __forceinline__ void mfma_sv(v16f& d, const v8i& a, const v8i& b) { d = mfma_bi(a, b, d); }

struct UAArgs {
  const uint8_t* q;
  const uint8_t* kc;
  const uint8_t* vc;
  __hip_bfloat16* out;
  const int* block_table;
  const int* seq_lens;
  const int* cu_q;
  const float* q_descale;
  const float* k_descale;
  const float* v_descale;
  long long q_s0, q_s1;
  long long o_s0, o_s1;
  long long kv_s_blk, kv_s_tok, kv_s_head;
  int bt_stride;
  int num_seqs;
  float scale;
  int blk_shift;   // log2(page tokens / 64)
};

#ifndef HDV
#define HDV 512
#endif
#ifndef WINV
#define WINV 0
#endif
#ifndef MINBLK
#define MINBLK 1
#endif
#ifndef QSTAGE
#define QSTAGE 0
#endif
constexpr int HD = HDV, BN = 64, NQPKV = 4, BQ = 32;
constexpr int NKS = HD / 64, NOPS = 2 * NKS, NDT = HD / 128, NU = 4 * NDT;
constexpr int RPI = 1024 / HD, NCP = 16 / RPI, CPR = HD / 16, KST = 64 * HD;   // rows per copy instr, copy instrs per wave and tile, 16B chunks per row
constexpr float LAZY_THRESH = LAZY_THRESH_V;
// LDS map (bytes)
constexpr int LDS_X0 = 4 * KST;
constexpr int X_P = 0, X_ALPHA = 16384, X_FLAGS = 17408, X_L = 17472, X_SCL = 17984, X_BT = 19072;
constexpr int BT_MAX = (HD == 512) ? 3424 : 64;
constexpr int LDS_X_BYTES = X_BT + 4 * BT_MAX;   // P, alpha, flags, l, scale, block table

__device__ __forceinline__ int find_seq(const int* cu_q, int target, int num_seqs) {
  int left = 0, right = num_seqs;
  while (left < right) {
    int mid = (left + right) >> 1;
    int val = cu_q[mid];
    int mv = val / BQ + mid;
    if (mv <= target) left = mid + 1; else right = mid;
  }
  return left - 1;
}

__device__ __forceinline__ float xor32(float x) { return __shfl_xor(x, 32, 64); }

struct Kern {
  const UAArgs& a;
  int lane, wave, n, s;
  float c_log2;
  int qpos;
  long long ldoff, tokstride;
  uint8_t* Ksm; uint8_t* Vsm; uint8_t* Xsm;
  int kbase[4][2];
  int vbase[4];
  int pbase[2];
  int voffK[4], voffV[4];
  v8i qb[NKS];
  float m_run, m_shift;
  int scl;

  __device__ __forceinline__ v8i read_k(int stage, int op) {
#ifdef ABL_NOKREAD
    return qb[op >> 1];
#endif
    const int ks = op >> 1, st = op & 1;
    const uint8_t* base = Ksm + stage * KST + 256 * (ks >> 2) + st * (16 * HD);
    v4i lo = *(const v4i*)(base + kbase[ks & 3][0]);
    v4i hi = *(const v4i*)(base + kbase[ks & 3][1]);
    return (v8i){lo[0], lo[1], lo[2], lo[3], hi[0], hi[1], hi[2], hi[3]};
  }
  __device__ __forceinline__ v8i read_vcol(int stage, int dt) {
#ifdef ABL_NOVREAD
    return qb[dt];
#endif
    const uint8_t* base = Vsm + stage * KST + vbase[dt];
    v2i t0 = __builtin_amdgcn_ds_read_tr8_b64_v2i32((lds_v2i*)(base));
    v2i t1 = __builtin_amdgcn_ds_read_tr8_b64_v2i32((lds_v2i*)(base + 8 * HD));
    v2i t2 = __builtin_amdgcn_ds_read_tr8_b64_v2i32((lds_v2i*)(base + 16 * HD));
    v2i t3 = __builtin_amdgcn_ds_read_tr8_b64_v2i32((lds_v2i*)(base + 24 * HD));
    return (v8i){t0[0], t0[1], t1[0], t1[1], t2[0], t2[1], t3[0], t3[1]};
  }
  __device__ __forceinline__ v8i read_p(int stage, int qt) {
#ifdef ABL_NOPREAD
    return qb[qt + 4];
#endif
    const uint8_t* base = Xsm + X_P + stage * 8192 + 2048 * qt;
    v4i lo = *(const v4i*)(base + pbase[0]);
    v4i hi = *(const v4i*)(base + pbase[1]);
    return (v8i){lo[0], lo[1], lo[2], lo[3], hi[0], hi[1], hi[2], hi[3]};
  }
  __device__ __forceinline__ void write_p(int stage, const v8i& P) {
    uint8_t* base = Xsm + X_P + stage * 8192 + 2048 * wave;
    *(v4i*)(base + pbase[0]) = (v4i){P[0], P[1], P[2], P[3]};
    *(v4i*)(base + pbase[1]) = (v4i){P[4], P[5], P[6], P[7]};
  }
  __device__ __forceinline__ void publish(int stage, float alpha, bool need, int scl_) {
    ((float*)(Xsm + X_ALPHA))[stage * 128 + 32 * wave + n] = alpha;
    ((int*)(Xsm + X_SCL))[stage * 128 + 32 * wave + n] = scl_;
    ((int*)(Xsm + X_FLAGS))[stage * 4 + wave] = need ? 1 : 0;
  }
  __device__ __forceinline__ int read_flags(int stage) {
    const int* f = (const int*)(Xsm + X_FLAGS) + stage * 4;
    int v = f[0] | f[1] | f[2] | f[3];
    return __builtin_amdgcn_readfirstlane(v);
  }
  __device__ __forceinline__ void read_scl(int stage, int* sc) {
    const int* p = (const int*)(Xsm + X_SCL) + stage * 128 + n;
#pragma unroll
    for (int qt = 0; qt < 4; qt++) sc[qt] = p[32 * qt];
  }
  __device__ __forceinline__ void read_alpha(int stage, float* al) {
    const float* p = (const float*)(Xsm + X_ALPHA) + stage * 128 + n;
#pragma unroll
    for (int qt = 0; qt < 4; qt++) al[qt] = p[32 * qt];
  }
  __device__ __forceinline__ void issue_one(bool is_k, int blk, int stage, int i) {
#ifdef ABL_NOLOAD
    if (blk != -12345) return;
#endif
    const uint8_t* gp = (is_k ? a.kc : a.vc) + (long long)(blk >> a.blk_shift) * a.kv_s_blk + (long long)(blk & ((1 << a.blk_shift) - 1)) * (64 * a.kv_s_tok) + ldoff + (long long)(RPI * i) * tokstride;
    gp += (unsigned)(is_k ? voffK[i & 3] : voffV[i & 3]);
    if (is_k)
      __builtin_amdgcn_global_load_lds((void*)gp, (lds_void*)(Ksm + stage * KST + (16 * wave + RPI * i) * HD), 16, 0, 0);
    else
      __builtin_amdgcn_global_load_lds((void*)gp, (lds_void*)(Vsm + stage * KST + (16 * wave + RPI * i) * HD), 16, 0, 0);
  }
  __device__ __forceinline__ void apply_mask(int t, v16f& S0, v16f& S1) {
#pragma unroll
    for (int i = 0; i < 16; i++) {
      int k0 = t * BN + 32 * s + i, k1 = k0 + 16;
      if (k0 > qpos || k0 <= qpos - WIN_EFF) S0[i] = -INFINITY;
      if (k1 > qpos || k1 <= qpos - WIN_EFF) S1[i] = -INFINITY;
    }
  }
  __device__ __forceinline__ float max_part(const v16f& S0, const v16f& S1, int lo, int hi, float cur) {
#pragma unroll
    for (int e = lo; e < hi; e++) cur = fmaxf(cur, e < 16 ? S0[e] : S1[e - 16]);
    return cur;
  }
  __device__ __forceinline__ void exp_part(const v16f& S0, const v16f& S1, int lo, int hi, float* p) {
#pragma unroll
    for (int e = lo; e < hi; e++) {
      float sv = e < 16 ? S0[e] : S1[e - 16];
      p[e] = __builtin_amdgcn_exp2f(sv * c_log2 - m_shift);
    }
  }
  __device__ __forceinline__ v8i pack_p(const float* p) {
    v8i P;
#pragma unroll
    for (int r = 0; r < 8; r++) {
      int w = 0;
      w = __builtin_amdgcn_cvt_pk_fp8_f32(p[4 * r], p[4 * r + 1], w, false);
      w = __builtin_amdgcn_cvt_pk_fp8_f32(p[4 * r + 2], p[4 * r + 3], w, true);
      P[r] = w;
    }
    return P;
  }
};

#ifdef ABL_NOST
#define ST_COND (a.scale > 1.5f)
#else
#define ST_COND true
#endif
#ifdef ABL_COALST
#define COALST_STORE(DT, QT, g, pk, orow, d) if (blockIdx.y * 2 + blockIdx.x < (gridDim.y - 3) * 2) *(uint2*)((uint8_t*)a.out + (long long)(blockIdx.y * 2 + blockIdx.x) * 65536 + wave * 16384 + ((DT) * 4 + (QT)) * 2048 + (g) * 512 + lane * 8) = pk;
#else
#define COALST_STORE(DT, QT, g, pk, orow, d) *(uint2*)(orow + d) = pk;
#endif
#define STORE_TILE(DT, QT, INVV)                                                                                \
  {                                                                                                             \
    const int tl_ = qblk_local * BQ + 8 * (QT) + (n >> 2);                                                      \
    if (tl_ < qlen && ST_COND) {                                                                                \
      __hip_bfloat16* orow = a.out + (long long)(q_start + tl_) * a.o_s0 + (long long)head * a.o_s1;            \
      float ee[16] = {e0, e1, e2, e3, e4, e5, e6, e7, e8, e9, e10, e11, e12, e13, e14, e15};                     \
      _Pragma("unroll") for (int g = 0; g < 4; g++) {                                                           \
        int d = (HD / 4) * wave + 32 * (DT) + 8 * g + 4 * s;                                                         \
        uint2 pk;                                                                                               \
        pk.x = (uint32_t)__bfloat16_as_ushort(__float2bfloat16(ee[4 * g] * (INVV))) |                           \
               ((uint32_t)__bfloat16_as_ushort(__float2bfloat16(ee[4 * g + 1] * (INVV))) << 16);                \
        pk.y = (uint32_t)__bfloat16_as_ushort(__float2bfloat16(ee[4 * g + 2] * (INVV))) |                       \
               ((uint32_t)__bfloat16_as_ushort(__float2bfloat16(ee[4 * g + 3] * (INVV))) << 16);                \
        COALST_STORE(DT, QT, g, pk, orow, d)                                                                    \
      }                                                                                                         \
    }                                                                                                           \
  }

#ifndef EPI_V
#define EPI_V 2
#endif
__device__ __forceinline__ uint2 pack_bf16x4(float a0, float a1, float a2, float a3, float inv) {
  uint2 pk;
  pk.x = (uint32_t)__bfloat16_as_ushort(__float2bfloat16(a0 * inv)) | ((uint32_t)__bfloat16_as_ushort(__float2bfloat16(a1 * inv)) << 16);
  pk.y = (uint32_t)__bfloat16_as_ushort(__float2bfloat16(a2 * inv)) | ((uint32_t)__bfloat16_as_ushort(__float2bfloat16(a3 * inv)) << 16);
  return pk;
}
#define STORE_PHASE(PH)                                                                                         \
  {                                                                                                             \
    _Pragma("unroll") for (int kk = 0; kk < 16; kk++) {                                                         \
      const int r_ = 8 * kk + (lane >> 3), c_ = lane & 7;                                                       \
      const v4i v_ = *(const v4i*)(stg + r_ * 128 + 16 * (c_ ^ (r_ & 7)));                                      \
      const int tl_ = qblk_local * BQ + 8 * (kk >> 2) + ((r_ & 31) >> 2);                                       \
      if (tl_ < qlen)                                                                                           \
        *(v4i*)(a.out + (long long)(q_start + tl_) * a.o_s0 + (long long)(kv_head * NQPKV + (r_ & 3)) * a.o_s1 +  \
                (HD / 4) * wave + 64 * (PH) + 8 * c_) = v_;                                                     \
    }                                                                                                           \
    asm volatile("" ::: "memory"); __builtin_amdgcn_wave_barrier();                                             \
  }

#ifdef DBG_COUNT
#define DBG_HOOK if (lane == 0) { atomicAdd(&g_dbg[0], 1ull); if (need) atomicAdd(&g_dbg[1], 1ull); if (t - 1 >= safe_end) atomicAdd(&g_dbg[2], 1ull); }
#else
#define DBG_HOOK
#endif
#ifndef RESC_THRESH
#define RESC_THRESH 64.0f
#endif
#define CHECK_AND_PUBLISH()                                                                                     \
  {                                                                                                             \
    float mx_ = fmaxf(mloc, xor32(mloc));                                                                       \
    const float mt_ = mx_ * k.c_log2;                                                                           \
    if (k.m_run == -INFINITY) k.m_run = mt_;                                                                                  \
    float d_ = mt_ - k.m_run;                                                                                   \
    const bool need = __any(d_ > RESC_THRESH);                                                                  \
    float alpha_v = 1.f;                                                                                        \
    if (need) {                                                                                                 \
      float m_new = fmaxf(k.m_run, mt_);                                                                        \
      alpha_v = exp2f(k.m_run - m_new);                                                                         \
      LA[0] *= alpha_v;                                                                                         \
      k.m_run = m_new;                                                                                          \
      d_ = mt_ - k.m_run;                                                                                       \
    }                                                                                                           \
    const int e_ = (int)ceilf(fmaxf(d_ - 8.0f, 0.0f));                                                          \
    k.m_shift = (k.m_run == -INFINITY) ? 0.f : k.m_run + (float)e_;                                                                            \
    k.scl = 127 + e_;                                                                                           \
    DBG_HOOK                                                                                                    \
    k.publish(t & 1, alpha_v, need, k.scl);                                                                     \
  }

__global__ __launch_bounds__(256, MINBLK) void ua512_v7(UAArgs a) {
  __shared__ __attribute__((aligned(16))) uint8_t Ksm[2 * KST];
  __shared__ __attribute__((aligned(16))) uint8_t Vsm[2 * KST];
  __shared__ __attribute__((aligned(16))) uint8_t Xsm[LDS_X_BYTES];
#if QSTAGE
  __shared__ __attribute__((aligned(16))) uint8_t Qsm[32768];
#endif
  const int tid = threadIdx.x, lane = tid & 63, wave = __builtin_amdgcn_readfirstlane(tid >> 6);
#ifdef ABL_RET0
  if (a.scale < 5.f) return;
#endif
  const int n = lane & 31, s = lane >> 5;
  const int kv_head = blockIdx.x;
  const int qbg = gridDim.y - 1 - blockIdx.y;
  const int seq = find_seq(a.cu_q, qbg, a.num_seqs);
  const int q_start = a.cu_q[seq];
  const int qblk_local = qbg - (q_start / BQ + seq);
  const int qlen = a.cu_q[seq + 1] - q_start;
  if (qblk_local * BQ >= qlen) return;
#ifdef ABL_RET1
  if (a.scale < 5.f) return;
#endif
  const int seq_len = a.seq_lens[seq];
  const int ctx = seq_len - qlen;
  int max_prefix = ctx + qblk_local * BQ + (BQ * NQPKV - 1) / NQPKV + 1;
  max_prefix = max(1, min(max_prefix, seq_len));
  const int tile_end = (max_prefix + BN - 1) / BN;
  const int qlo = ctx + qblk_local * BQ;
  const int safe_end = min(max((qlo + 1) / BN, 0), tile_end);
#if WINV > 0
  const int t0 = max(0, qlo - (WINV - 1)) / BN;
  const int left_end = (qlo + BQ - 1 - (WINV - 1)) > 0 ? (qlo + BQ - 1 - (WINV - 1) + BN - 1) / BN : 0;
#else
  const int t0 = 0;
  const int left_end = 0;
#endif
#ifdef ABL_NT
  const int nt = min(tile_end - t0, ABL_NT);
#else
  const int nt = tile_end - t0;
#endif

  Kern k{a};
  k.lane = lane; k.wave = wave; k.n = n; k.s = s; k.Ksm = Ksm; k.Vsm = Vsm; k.Xsm = Xsm;
  k.c_log2 = 1.4426950408889634f * a.scale * (a.q_descale ? a.q_descale[0] : 1.f) * (a.k_descale ? a.k_descale[0] : 1.f);
  const float out_scale = a.v_descale ? a.v_descale[0] : 1.f;
  const int tok_local = qblk_local * BQ + wave * 8 + (n >> 2);
  const int head = kv_head * NQPKV + (n & 3);
  const bool row_valid = tok_local < qlen;
  k.qpos = ctx + tok_local;
  const int* bt_g = a.block_table + (long long)seq * a.bt_stride;
#define TILE_CODE(AB) ((bt_g[(AB) >> a.blk_shift] << a.blk_shift) | ((AB) & ((1 << a.blk_shift) - 1)))
  int* const btl = (int*)(Xsm + X_BT);
  for (int i = tid; i < nt; i += 256) btl[i] = TILE_CODE(t0 + i);
  k.ldoff = (long long)kv_head * a.kv_s_head;
  k.tokstride = a.kv_s_tok;
  {
    const int krow0 = 32 * ((n >> 2) & 1) + 4 * (n >> 3) + (n & 3);
#ifdef OLDK
    const int x4 = krow0 & 7;
#else
    const int x4 = (krow0 & 3) | (((krow0 >> 5) & 1) << 2) | (((krow0 >> 2) & 1) << 3);
#endif
#pragma unroll
    for (int par = 0; par < 4; par++) {
      k.kbase[par][0] = krow0 * HD + 16 * ((4 * par + 2 * s) ^ x4);
      k.kbase[par][1] = krow0 * HD + 16 * ((4 * par + 2 * s + 1) ^ x4);
    }
    const int bp = (lane >> 4) & 1, rr = (lane >> 1) & 7;
    const int key0 = 32 * s + ((lane & 15) >> 1);
#pragma unroll
    for (int r = 0; r < NDT; r++) {
      const int cl = (HD / 64) * wave + 2 * r + bp;                 // logical 16B chunk of the lane's column block
#ifdef OLDV
      k.vbase[r] = key0 * HD + 16 * (cl ^ rr) + 8 * (lane & 1);
#else
      k.vbase[r] = key0 * HD + 16 * (cl ^ (2 * rr)) + 8 * (lane & 1);
#endif
    }
#ifndef PSW
#define PSW 2
#endif
    const int f = PSW == 0 ? 0 : (PSW == 1 ? ((n >> 1) & 3) : (PSW == 2 ? ((n >> 2) & 3) : ((n >> 3) & 3)));
    k.pbase[0] = n * 64 + 16 * ((2 * s) ^ f);
    k.pbase[1] = n * 64 + 16 * ((2 * s + 1) ^ f);
#pragma unroll
    for (int v = 0; v < 4; v++) {
      const int rsub = lane / CPR, cc = lane % CPR;
      const int row = 16 * wave + RPI * v + rsub;     // rows of copy instruction i=v (variants repeat with period 4)
      const int cK = cc ^ ((row & 3) | (((row >> 5) & 1) << 2) | (((row >> 2) & 1) << 3));
      const int cV = cc ^ (2 * (row & 7));
      k.voffK[v] = (16 * wave + rsub) * (int)a.kv_s_tok + 16 * cK;
      k.voffV[v] = (16 * wave + rsub) * (int)a.kv_s_tok + 16 * cV;
    }
  }
#if QSTAGE
  {
#pragma unroll
    for (int j = 0; j < 8; j++) {
      const int tkc = min(qblk_local * BQ + wave * 8 + j, qlen - 1);
      const int rr_ = 4 * j + (lane >> 4);
      const uint8_t* gp = a.q + (long long)(q_start + tkc) * a.q_s0 + (long long)(kv_head * NQPKV + (lane >> 4)) * a.q_s1 + 16 * ((lane & 15) ^ (rr_ & 15));
      __builtin_amdgcn_global_load_lds((void*)gp, (lds_void*)(Qsm + wave * 8192 + j * 1024), 16, 0, 0);
    }
  }
#else
  {
    const uint8_t* qrow = a.q + (long long)(q_start + (row_valid ? tok_local : 0)) * a.q_s0 + (long long)head * a.q_s1;
#pragma unroll
    for (int ks = 0; ks < NKS; ks++) {
#ifdef ABL_NOQ
      v4i lo = (v4i){ks, 1, 2, 3}; v4i hi = lo;
#else
      v4i lo = *(const v4i*)(qrow + ks * 64 + s * 32);
      v4i hi = *(const v4i*)(qrow + ks * 64 + s * 32 + 16);
#endif
      if (!row_valid) { lo = (v4i){0, 0, 0, 0}; hi = lo; }
      k.qb[ks] = (v8i){lo[0], lo[1], lo[2], lo[3], hi[0], hi[1], hi[2], hi[3]};
    }
  }
#endif
